package cn.zhuatech.property.service;import org.junit.jupiter.api.Test;import static org.assertj.core.api.Assertions.assertThat;class TenantMoveInReadinessServiceTest{private final TenantMoveInReadinessService service=new TenantMoveInReadinessService();@Test void approvesReadyMoveIn(){var r=service.assess(new TenantMoveInReadinessService.Request("L1",true,true,true,true,true,true,true,true,true));assertThat(r.decision()).isEqualTo(TenantMoveInReadinessService.Decision.MOVE_IN);}@Test void blocksCommercialAndSafetyGaps(){var r=service.assess(new TenantMoveInReadinessService.Request("L2",false,false,false,false,false,true,true,true,true));assertThat(r.blockers()).hasSize(5);}@Test void reviewsOperationalHandover(){var r=service.assess(new TenantMoveInReadinessService.Request("L3",true,true,true,true,true,false,false,false,false));assertThat(r.actions()).hasSize(4);}}
